SELECT game_id, skill_category_key, name, description, status, sort_order, created_at, updated_at
FROM public.skill_categories
WHERE game_id = #{gameId}

    AND (
        strpos(lower(skill_category_key), lower(#{keyword})) > 0
        OR strpos(lower(name), lower(#{keyword})) > 0
    )


    AND status = #{status}

ORDER BY sort_order ASC, name ASC, skill_category_key ASC

SELECT game_id, skill_category_key, name, description, status, sort_order, created_at, updated_at
FROM public.skill_categories
WHERE game_id = #{gameId} AND skill_category_key = #{skillCategoryKey}

SELECT COUNT(1)
FROM public.skill_categories
WHERE game_id = #{gameId} AND skill_category_key = #{skillCategoryKey}

